const form=document.getElementById('settings');
function resizeMultiline(field){field.style.height='auto';field.style.height=`${Math.max(58,field.scrollHeight)}px`}
const saveBar=document.getElementById('save-bar');
const saveState=document.getElementById('save-state');
const updateStatus=document.getElementById('update-status');
const updateFeed=document.getElementById('update-feed');
const updateButtons=[...document.querySelectorAll('[data-action="update"]')];
let activeNetworkTab='current',activeDiagnosticTab='memory',activeDisplayTab='appearance';
let activeTab='overview',activeService='bus',activeIntegration='display',updateWatchTimer=null,updateWatchStartedAt=0,updateSeenActive=false;
const dirtySections=new Set();
const dirtyFields=new Map();
const sectionNames={appearance:'Display',automation:'Automation',bus:'Bus Times',roon:'Audio services',home:'Home Assistant',logging:'Logging',software:'Software'};
const updateHistory=[];
const sectionFields={
  appearance:['display_theme','display_background','interface_size','settings_layout','touch_roon_bridge','touch_airplay','touch_netdata','portrait_discovery_columns','landscape_music_clock'],
  automation:['scheduled_wake_enabled','weekend_wake_enabled','weekend_wake_time','sleep_start','sleep_end','outside_hours_wake_minutes','sleep_show_clock','morning_start','morning_end','auto_switch_to_roon','roon_idle_return_minutes','browse_idle_return_minutes','sleep_when_roon_idle','daytime_inactivity_minutes'],
  bus:['bus_enabled','bus_stop_code','bus_stop_name','services','walking_minutes','poll_seconds','lta_account_key'],
  roon:['roon_display_name','roon_now_playing_name','roon_queue_name','roon_zone_name','roon_core_host','roon_show_controls','roon_show_clock','roon_show_queue','roon_show_browser','bluos_enabled','bluos_player_address','bluos_visible_inputs','bluos_input_names'],
  home:['home_assistant_enabled','home_assistant_title','home_assistant_url','home_assistant_token','home_assistant_entities','home_assistant_color_mode','home_assistant_single_color','home_assistant_light_color','home_assistant_fan_color','home_assistant_switch_color','home_assistant_scene_color'],
  logging:['openobserve_enabled','openobserve_url','openobserve_org','openobserve_stream','openobserve_username','openobserve_password'],
  software:['release_channel'],
};

function reportAdminActivity(text,{error=false,source='Settings'}={}){if(!text)return;const activity=document.getElementById('activity-message');activity.textContent=(source==='Settings'?'':source+': ')+text;activity.classList.toggle('error',error);}
function notify(text,error=false){reportAdminActivity(text,{error});saveBar.classList.toggle('error',error);updateSaveBar();if(text==='Settings saved.')loadReleases().catch(()=>{})}

function pinBanner(text){if(text==='Display hardware changed. Reboot now.')return;notify(text)}
function currentSaveSection(){if(activeTab==='display')return'appearance';if(activeTab==='automation')return'automation';if(activeTab==='services')return activeService==='bluos'?'roon':activeService;if(activeTab==='software')return'software';if(activeTab==='system'&&!document.getElementById('system-logging').hidden)return'logging';return null}
async function loadReleases(refresh=false){const response=await fetch('/api/admin/releases'+(refresh?'?refresh=1':''),{cache:'no-store'});if(!response.ok)throw new Error('Could not check release availability');const data=await response.json();document.getElementById('release-status').textContent=`Installed v${data.installed_version} · ${data.release_channel==='beta'?'Beta':'Stable'} · Latest ${data.latest_version?'v'+data.latest_version:'unavailable'} — ${data.message}`;document.getElementById('overview-update').textContent=data.status==='unavailable'?'Release check unavailable':data.update_available?'v'+data.latest_version+' available':data.status==='ahead'?'Ahead of channel; no downgrade':'Up to date';}
document.getElementById('check-releases').addEventListener('click',()=>loadReleases(true).catch(error=>notify(error.message,true)));
form.addEventListener('change',event=>{if(event.target.name==='release_channel')document.getElementById('release-status').textContent='Save the selected channel to check its releases.'});
loadReleases().catch(()=>{document.getElementById('release-status').textContent='Release check unavailable. Try again later.'});
function updateSaveBar(){const dirty=dirtySections.size>0;saveBar.hidden=false;saveBar.classList.toggle('saved',!dirty);document.getElementById('save-settings').disabled=!dirty;saveState.textContent=dirty?'Unsaved changes':'All changes saved';const summary=document.getElementById('save-summary');summary.replaceChildren();for(const section of dirtySections){const item=document.createElement('li'),fields=[...(dirtyFields.get(section)||[])];item.textContent=(sectionNames[section]||section)+(fields.length?' · '+fields.slice(0,2).join(', ')+(fields.length>2?' +'+(fields.length-2)+' more':''):'');summary.append(item)}summary.hidden=!dirty}
function markDirty(field){const section=field?.closest?.('[data-save]')?.dataset.save||currentSaveSection();if(!section)return;dirtySections.add(section);if(field?.name){let label='';const domain=field.name.match(/^home_assistant_(light|fan|switch|scene|single)_color$/);if(domain)label=domain[1]+' tile colour';else{const original=field.closest('label');if(original){const copy=original.cloneNode(true);copy.querySelectorAll('input,select,textarea,small,output').forEach(node=>node.remove());label=copy.textContent.replace(/\s+/g,' ').trim()}}if(label){if(!dirtyFields.has(section))dirtyFields.set(section,new Set());dirtyFields.get(section).add(label)}}updateSaveBar()}

function showMode(mode){const busEnabled=form.elements.bus_enabled.checked;document.querySelector('.mode-sections').classList.toggle('bus-disabled',!busEnabled);document.querySelectorAll('[data-mode]').forEach(button=>{button.classList.toggle('active',button.dataset.mode===mode);if(button.dataset.mode==='bus')button.hidden=!busEnabled})}
let restoringRoute=false;
function recordAdminRoute(){if(restoringRoute)return;const sub=activeTab==='display'?activeDisplayTab:activeTab==='services'?activeService:activeTab==='network'?activeNetworkTab:activeTab==='system'?(document.querySelector('[data-system-panel]:not([hidden])')?.dataset.systemPanel||'system-device'):'';const hash='#'+[activeTab,sub,activeTab==='system'&&sub==='diagnostics'?activeDiagnosticTab:''].filter(Boolean).map(encodeURIComponent).join('/');if(location.hash!==hash)history.pushState(null,'',hash)}
function showTab(name){const changed=activeTab!==name;activeTab=name;if(changed)form.scrollTop=0;document.querySelectorAll('[data-panel]').forEach(panel=>panel.hidden=panel.dataset.panel!==name);document.querySelectorAll('[data-tab]').forEach(button=>{const selected=button.dataset.tab===name;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1});updateSaveBar();recordAdminRoute();if(['system','network','software'].includes(name))loadSystem();if(name==='network')window.dispatchEvent(new Event('admin-network-open'));window.dispatchEvent(new Event('admin-section-change'));}
function openSystemSection(id){if(!document.querySelector('[data-system-panel="'+id+'"]'))return;document.querySelectorAll('[data-system-panel]').forEach(panel=>{const selected=panel.dataset.systemPanel===id;panel.hidden=!selected;panel.open=selected});document.querySelectorAll('[data-system-anchor]').forEach(button=>{const selected=button.dataset.systemAnchor===id;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1});updateSaveBar();recordAdminRoute();window.dispatchEvent(new Event('admin-section-change'))}
function showService(name){activeService=name;document.querySelectorAll('[data-service-panel]').forEach(panel=>panel.hidden=panel.dataset.servicePanel!==name);document.querySelectorAll('[data-service-tab]').forEach(button=>button.setAttribute('aria-selected',String(button.dataset.serviceTab===name)));updateSaveBar();recordAdminRoute()}
function showIntegration(name){activeIntegration=name;document.querySelectorAll('[data-integration-panel]').forEach(panel=>panel.hidden=panel.dataset.integrationPanel!==name);document.querySelectorAll('[data-integration-tab]').forEach(button=>{const selected=button.dataset.integrationTab===name;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1})}
function updateConditional(input){const target=document.getElementById(input.dataset.reveals);if(target)target.hidden=!input.checked}
function secondsToMinutes(value){return Number((Number(value||0)/60).toFixed(2))}
function minutesToSeconds(value){return Math.round(Number(value||0)*60)}
const homeColourPresets=[['Amber','#f4c95d'],['Aqua','#5bcbd6'],['Mint','#6ed9ae'],['Sky','#60a5fa'],['Indigo','#818cf8'],['Purple','#9868f9'],['Rose','#f472b6'],['Coral','#fb7185'],['Red','#f87171'],['Orange','#fb923c'],['Lime','#a3e635'],['Slate','#94a3b8']];
function syncHomeColour(domain){const field=form.elements[`home_assistant_${domain}_color`],row=document.querySelector(`[data-colour-row="${domain}"]`),preset=row?.querySelector('[data-colour-preset]');if(!field||!row||!preset)return;const value=field.value.trim().toLowerCase();row.style.setProperty('--tile-colour',/^#[0-9a-f]{6}$/.test(value)?value:'#6ed9ae');preset.value=homeColourPresets.some(([,colour])=>colour===value)?value:'custom'}
function showHomeColourMode(mode){form.elements.home_assistant_color_mode.value=mode;document.querySelectorAll('[data-colour-mode]').forEach(button=>{const selected=button.dataset.colourMode===mode;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1});document.querySelectorAll('[data-colour-panel]').forEach(panel=>panel.hidden=panel.dataset.colourPanel!==mode)}
function setupHomeColours(){document.querySelectorAll('[data-colour-preset]').forEach(select=>{select.replaceChildren(...homeColourPresets.map(([label,value])=>new Option(label,value)),new Option('Custom hex…','custom'));const domain=select.dataset.colourPreset,field=form.elements[`home_assistant_${domain}_color`];select.addEventListener('change',()=>{if(select.value!=='custom'){field.value=select.value;syncHomeColour(domain);markDirty()}});field.addEventListener('input',()=>syncHomeColour(domain));syncHomeColour(domain)});document.querySelectorAll('[data-colour-mode]').forEach(button=>button.addEventListener('click',()=>{showHomeColourMode(button.dataset.colourMode);markDirty()}));showHomeColourMode(form.elements.home_assistant_color_mode.value)}

async function load(){const response=await fetch('/api/admin/config',{cache:'no-store'});if(!response.ok)throw new Error('Could not load settings');const data=await response.json();applyTheme(data.display_theme);for(const [key,value] of Object.entries(data)){const field=form.elements[key];if(!field)continue;if(field.type==='checkbox')field.checked=Boolean(value);else{if(key==='roon_zone_name'&&value&&![...field.options].some(option=>option.value===value))field.add(new Option(value+' (saved)',value));field.value=Array.isArray(value)?value.join(', '):value}}form.elements.roon_idle_return_minutes.value=secondsToMinutes(data.roon_idle_return_seconds);form.elements.browse_idle_return_minutes.value=secondsToMinutes(data.browse_idle_return_seconds);form.elements.daytime_inactivity_minutes.value=secondsToMinutes(data.daytime_inactivity_seconds);form.elements.outside_hours_wake_minutes.value=secondsToMinutes(data.outside_hours_wake_seconds);document.getElementById('version').textContent=`v${data.app_version}`;document.getElementById('admin-username').value=data.admin_username;document.getElementById('auth-enabled').checked=data.admin_auth_enabled;showMode(data.display_mode);document.getElementById('key-status').textContent=data.has_lta_key?'An AccountKey is configured.':'No AccountKey is configured yet.';document.getElementById('home-token-status').textContent=data.has_home_assistant_token?'A Home Assistant token is configured.':'No Home Assistant token is configured yet.';document.getElementById('openobserve-password-status').textContent=data.has_openobserve_password?'An OpenObserve password is configured.':'No OpenObserve password is configured yet.';document.querySelectorAll('[data-reveals]').forEach(updateConditional);for(const domain of ['single','light','fan','switch','scene'])syncHomeColour(domain);showHomeColourMode(data.home_assistant_color_mode||'multi');dirtySections.clear();dirtyFields.clear();updateSaveBar();await loadSystem()}
const mb=kb=>`${(Number(kb||0)/1024).toFixed(1)} MB`;
const duration=seconds=>{const hours=Math.floor(seconds/3600),days=Math.floor(hours/24);return days?`${days}d ${hours%24}h`:`${hours}h ${Math.floor(seconds%3600/60)}m`};
function showDiagnostics(data={}){const memory=data.memory||{},swap=data.swap||{},known=Number(memory.total_kb)>0;document.getElementById('diag-memory').textContent=known?`${memory.used_percent}% · ${mb(memory.used_kb)}`:'Unavailable';document.getElementById('diag-available').textContent=known?`${mb(memory.available_kb)} · swap ${mb(swap.used_kb)}`:'Unavailable';const health=data.temperature_c==null?'':` · ${data.temperature_c}°C`;document.getElementById('diag-load').textContent=((data.load||[]).map(value=>Number(value).toFixed(2)).join(' · ')||'—')+health;document.getElementById('diag-uptime').textContent=data.uptime_seconds?duration(data.uptime_seconds):'Unavailable';document.getElementById('diag-processes').replaceChildren(...(data.processes||[]).map(process=>{const row=document.createElement('div');row.className='process-row';const name=document.createElement('span');name.className='process-name';name.textContent=process.label;const ram=document.createElement('strong'),cpu=document.createElement('strong'),status=document.createElement('span'),measured=Boolean(process.pids?.length);ram.textContent=measured?mb(process.rss_kb):'—';cpu.textContent=measured?`${Number(process.cpu_percent).toFixed(1)}%`:'—';status.textContent=process.active?'Running':'Stopped';if(measured&&known){const meter=document.createElement('span'),fill=document.createElement('i');meter.className='process-meter';fill.style.width=Math.min(100,Number(process.rss_kb)*100/Number(memory.total_kb))+'%';meter.append(fill);ram.append(meter)}row.append(name,ram,cpu,status);return row}))}
async function loadDiagnostics(){const button=document.getElementById('refresh-diagnostics');if(button.disabled)return;button.disabled=true;try{const response=await fetch('/api/admin/diagnostics',{cache:'no-store'});if(!response.ok)throw new Error('Could not load diagnostics');showDiagnostics(await response.json())}catch(error){notify(error.message,true)}finally{button.disabled=false}}
async function loadSystem(){const response=await fetch('/api/admin/system',{cache:'no-store'});if(!response.ok)return;const data=await response.json();document.getElementById('hostname').value=data.hostname||'';document.getElementById('display-profile').value=data.display_profile==='touch2-5-7'?'touch2-7':(data.display_profile||'original');document.getElementById('display-orientation').value=data.display_orientation||'landscape';if(data.reboot_required)pinBanner('Display hardware changed. Reboot now.');const brightness=Number(data.display_brightness||100);document.getElementById('display-brightness').value=brightness;document.getElementById('brightness-value').textContent=`${brightness}%`;const netdata=document.getElementById('netdata-enabled');netdata.checked=data.netdata==='running';netdata.disabled=data.netdata==='not_installed';document.getElementById('netdata-status').textContent=data.netdata==='running'?'Running':data.netdata==='stopped'?'Stopped':'Not installed';document.getElementById('netdata-help').textContent=data.netdata==='not_installed'?'Netdata is not installed on this appliance.':'Starts Netdata automatically on boot.';const leds=document.getElementById('pi-leds-enabled');leds.checked=data.pi_leds==='enabled';leds.disabled=data.pi_leds==='not_installed';document.getElementById('pi-leds-status').textContent=data.pi_leds==='enabled'?'On':data.pi_leds==='disabled'?'Off':'Not available';document.getElementById('pi-leds-help').textContent=data.pi_leds==='not_installed'?'Compatible Raspberry Pi status lights were not found.':'Controls the Raspberry Pi ACT and PWR lights. Off by default.';const bridgeInstalled=data.roon_bridge!=='not_installed';document.getElementById('roon-status').textContent=bridgeInstalled?(data.roon_bridge==='running'?'Running':'Stopped'):'Not installed';document.querySelectorAll('[data-action^="roon_"]').forEach(button=>button.disabled=!bridgeInstalled);document.getElementById('roon-controller-status').textContent=data.roon_controller;document.getElementById('roon-controller-help').hidden=data.roon_controller.startsWith('Connected');updateStatus.textContent=data.update_status;document.getElementById('overview-roon').textContent=data.roon_controller;document.getElementById('overview-network').textContent=data.wifi_ssid||'Not connected';const version=data.app_version?`v${data.app_version} · `:'';const settled=data.update_status==='Ready'||data.update_status.startsWith('Update installed');document.getElementById('overview-update').textContent=version+(settled?'Up to date':data.update_status);document.getElementById('alpine-tools').hidden=!data.alpine_tools;document.getElementById('tools-status').textContent=data.tools_status||'Adds display capture, diagnostics, network time and Netdata. Netdata remains off until enabled.';renderApplianceDetails(data);recordUpdateStatus()}
function renderApplianceDetails(data){document.getElementById('netdata-lightweight').checked=Boolean(data.netdata_lightweight);const details=data.netdata_details||{},management=document.getElementById('netdata-management'),appliance=Boolean(data.alpine_tools);management.hidden=!details.installed||!appliance;document.getElementById('netdata-version').textContent=details.version||'Installed';const cloud=details.cloud_status||'unclaimed';document.getElementById('netdata-cloud-status').textContent=cloud==='online'?'Connected':cloud==='offline'?'Claimed · offline':'Not connected';document.getElementById('netdata-cloud-help').textContent=cloud==='online'?(details.claim_id?`Agent ID ${details.claim_id}`:'Connected to Netdata Cloud.'):(data.netdata_operation_status|| (details.claim_id?`Agent ID ${details.claim_id}`:'Cloud status is read from the local Agent.'));document.getElementById('netdata-disconnect').hidden=cloud==='unclaimed';document.getElementById('netdata-connect-toggle').textContent=cloud==='unclaimed'?'Connect to Netdata Cloud':'Reconnect to Netdata Cloud';document.getElementById('netdata-open').href=`http://${location.hostname}:19999/`;const bridgeInstalled=data.roon_bridge!=='not_installed',bridgeInstalling=(data.roon_bridge_operation_status||'').includes('…')||(data.roon_bridge_operation_status||'').includes('queued');document.getElementById('roon-install').hidden=bridgeInstalled;document.getElementById('roon-install').disabled=bridgeInstalling;document.getElementById('roon-controls').hidden=!bridgeInstalled;document.getElementById('roon-bridge-help').textContent=data.roon_bridge_operation_status||(bridgeInstalled?'This optional endpoint makes the Pi available under Roon → Settings → Audio.':'Roon Bridge is optional and separately distributed. Install Roon’s official ARM64 package to make this Pi an audio endpoint.');document.getElementById('device-username').value=data.device_username||'admin';for(const id of ['device-username','device-password','device-password-confirm','save-device-access'])document.getElementById(id).disabled=!appliance}
function ensureNetdataInstaller(){let panel=document.getElementById('netdata-installer');if(panel)return panel;panel=document.createElement('div');panel.id='netdata-installer';panel.innerHTML='<p>Install the latest official stable Netdata Agent with automatic updates. Cloud connection is optional and can be added afterwards.</p><button id="netdata-install" class="secondary" type="button">Install Netdata</button><small id="netdata-install-status" role="status"></small>';const management=document.getElementById('netdata-management');management.before(panel);panel.querySelector('button').addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;try{const result=await action({action:'netdata_install'});notify(result.queued===false?'Netdata installation is already running.':'Installing the official Netdata Agent…');const started=Date.now(),timer=setInterval(async()=>{await loadSystem().catch(()=>{});const installed=!document.getElementById('netdata-installer').hidden,status=document.getElementById('netdata-install-status').textContent;if(Date.now()-started>900000||status.startsWith('Failed:')||document.getElementById('netdata-status').textContent!=='Not installed'){clearInterval(timer);button.disabled=false}},3000)}catch(error){button.disabled=false;notify(error.message,true)}});return panel}
function renderApplianceDetails(data){document.getElementById('netdata-lightweight').checked=Boolean(data.netdata_lightweight);const details=data.netdata_details||{},management=document.getElementById('netdata-management'),installer=ensureNetdataInstaller(),appliance=Boolean(data.alpine_tools),installed=Boolean(details.installed);management.hidden=!installed||!appliance;installer.hidden=installed||!appliance;document.getElementById('netdata-install-status').textContent=installed?'':(data.netdata_operation_status||'');document.getElementById('netdata-version').textContent=details.version||'Installed';const cloud=details.cloud_status||'unclaimed';document.getElementById('netdata-cloud-status').textContent=cloud==='online'?'Connected':cloud==='offline'?'Claimed · offline':'Not connected';document.getElementById('netdata-cloud-help').textContent=cloud==='online'?(details.claim_id?`Agent ID ${details.claim_id}`:'Connected to Netdata Cloud.'):(data.netdata_operation_status||(details.claim_id?`Agent ID ${details.claim_id}`:'Cloud status is read from the local Agent.'));document.getElementById('netdata-disconnect').hidden=cloud==='unclaimed';document.getElementById('netdata-connect-toggle').textContent=cloud==='unclaimed'?'Connect to Netdata Cloud':'Reconnect to Netdata Cloud';document.getElementById('netdata-open').href=`http://${location.hostname}:19999/`;const bridgeInstalled=data.roon_bridge!=='not_installed',bridgeInstalling=(data.roon_bridge_operation_status||'').includes('…')||(data.roon_bridge_operation_status||'').includes('queued');document.getElementById('roon-install').hidden=bridgeInstalled;document.getElementById('roon-install').disabled=bridgeInstalling;document.getElementById('roon-controls').hidden=!bridgeInstalled;document.getElementById('roon-bridge-help').textContent=data.roon_bridge_operation_status||(bridgeInstalled?'This optional endpoint makes the Pi available under Roon → Settings → Audio.':'Roon Bridge is optional and separately distributed. Install Roon’s official ARM64 package to make this Pi an audio endpoint.');const airplayInstalled=data.airplay!=='not_installed',airplayInstalling=(data.airplay_operation_status||'').includes('…')||(data.airplay_operation_status||'').includes('queued');document.getElementById('airplay-status').textContent=airplayInstalled?(data.airplay==='running'?'Running':'Stopped'):'Not installed';document.getElementById('airplay-install').hidden=airplayInstalled||!appliance;document.getElementById('airplay-install').disabled=airplayInstalling;document.getElementById('airplay-management').hidden=!airplayInstalled||!appliance;document.getElementById('airplay-name').value=data.airplay_name||'RoonDeck';document.getElementById('airplay-help').textContent=data.airplay_operation_status||(airplayInstalled?'Available as a classic AirPlay audio receiver.':'Install Alpine’s maintained Shairport Sync package to receive AirPlay audio.');document.getElementById('device-username').value=data.device_username||'admin';for(const id of ['device-username','device-password','device-password-confirm','save-device-access'])document.getElementById(id).disabled=!appliance}
function renderNetworkDetails(data){const network=data.network||{};document.getElementById('overview-network').textContent=network.name||data.wifi_ssid||'Not connected'}
const loadSystemWithoutNetwork=loadSystem;
loadSystem=async function(){await loadSystemWithoutNetwork();const response=await fetch('/api/admin/system',{cache:'no-store'});if(response.ok)renderNetworkDetails(await response.json())}
function stopUpdateWatch(){if(updateWatchTimer)clearInterval(updateWatchTimer);updateWatchTimer=null;updateButtons.forEach(button=>button.disabled=false)}
document.querySelector('[data-action="install_tools"]').addEventListener('click',()=>{
  const started=Date.now();
  const timer=setInterval(async()=>{
    try{await loadSystem()}catch(_){}
    const status=document.getElementById('tools-status').textContent;
    if(Date.now()-started>300000||status.startsWith('System tools installed')||status.startsWith('Installation failed'))clearInterval(timer);
  },3000);
});
function recordUpdateStatus(){
  const status=updateStatus.textContent.trim();
  document.getElementById('overview-update').textContent=status.startsWith('Update ·')?status:'Checking release availability…';
  loadReleases().catch(()=>{document.getElementById('overview-update').textContent='Release check unavailable'});
  if(!status.startsWith('Update ·')&&!status.startsWith('Update installed')&&!status.startsWith('Update unchanged')&&!status.startsWith('Failed:'))return;
  if(!updateWatchTimer&&!updateSeenActive&&!status.startsWith('Update ·')){updateFeed.hidden=true;return;}
  if(updateHistory.at(-1)!==status)updateHistory.push(status);
  updateFeed.hidden=false;
  updateFeed.replaceChildren(...updateHistory.slice(-8).map((entry,index,entries)=>{const row=document.createElement('div');row.className=index===entries.length-1?'current':'';row.textContent=entry.replace(/^Update · /,'');return row}));
  if(status.startsWith('Update ·'))updateSeenActive=true;
  else if(updateSeenActive||status.startsWith('Failed:')||status.startsWith('Update unchanged')){
    stopUpdateWatch();
    if(status.startsWith('Update installed')){notify('Update installed. Reloading…');setTimeout(()=>location.reload(),1200)}
    else notify(status,status.startsWith('Failed:'));
  }
}
function watchUpdate(){updateHistory.length=0;updateSeenActive=false;updateWatchStartedAt=Date.now();updateFeed.hidden=false;updateFeed.replaceChildren();updateButtons.forEach(button=>button.disabled=true);if(updateWatchTimer)clearInterval(updateWatchTimer);updateWatchTimer=setInterval(()=>{if(Date.now()-updateWatchStartedAt>16*60*1000){stopUpdateWatch();notify('The updater exceeded its safety limit and was stopped. Check the update feed before trying again.',true);return}loadSystem().catch(()=>{})},2500)}
async function action(payload){const response=await fetch('/api/admin/system-action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed');return result}
document.getElementById('netdata-lightweight').addEventListener('change',async event=>{event.target.disabled=true;try{await action({action:'netdata_lightweight',enabled:event.target.checked});notify('Netdata monitoring mode applied.');}catch(error){notify(error.message,true);}finally{event.target.disabled=false;loadSystem();}});
function sectionPayload(section){const payload={section};for(const name of sectionFields[section]){const field=form.elements[name];if(!field)continue;payload[name]=field.type==='checkbox'?field.checked:field.value}if(section==='automation'){payload.roon_idle_return_seconds=minutesToSeconds(payload.roon_idle_return_minutes);payload.browse_idle_return_seconds=minutesToSeconds(payload.browse_idle_return_minutes);payload.daytime_inactivity_seconds=minutesToSeconds(payload.daytime_inactivity_minutes);payload.outside_hours_wake_seconds=minutesToSeconds(payload.outside_hours_wake_minutes);delete payload.roon_idle_return_minutes;delete payload.browse_idle_return_minutes;delete payload.daytime_inactivity_minutes;delete payload.outside_hours_wake_minutes}return payload}
function validateSection(section){for(const name of sectionFields[section]){const field=form.elements[name];if(field&&!field.checkValidity()){field.reportValidity();return false}}return true}
function watchRoonBridgeInstall(){const started=Date.now(),timer=setInterval(async()=>{try{const response=await fetch('/api/admin/system',{cache:'no-store'}),data=await response.json();if(response.ok){renderApplianceDetails(data);document.getElementById('roon-status').textContent=data.roon_bridge==='running'?'Running':data.roon_bridge==='stopped'?'Stopped':'Not installed';const status=data.roon_bridge_operation_status||'';if(data.roon_bridge!=='not_installed'||status.startsWith('Failed:')){clearInterval(timer);notify(status||'Roon Bridge installed.',status.startsWith('Failed:'))}}}catch(_){}if(Date.now()-started>900000)clearInterval(timer)},1800)}
function watchAirPlayInstall(){const started=Date.now(),timer=setInterval(async()=>{try{const response=await fetch('/api/admin/system',{cache:'no-store'}),data=await response.json();if(response.ok){renderApplianceDetails(data);const status=data.airplay_operation_status||'';if(data.airplay!=='not_installed'||status.startsWith('Failed:')){clearInterval(timer);notify(status||'AirPlay installed.',status.startsWith('Failed:'))}}}catch(_){}if(Date.now()-started>300000)clearInterval(timer)},1800)}

