document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',async()=>{if(button.dataset.confirm&&!window.confirm(button.dataset.confirm))return;button.disabled=true;if(button.dataset.action==='update')watchUpdate();try{const result=await action({action:button.dataset.action});if(button.dataset.action==='update')notify(result.queued===false?'An update is already running.':'Update queued.');else if(button.dataset.action==='roon_install'){notify(result.queued===false?'Roon Bridge installation is already running.':'Installing Roon Bridge…');watchRoonBridgeInstall()}else if(button.dataset.action==='airplay_install'){notify(result.queued===false?'AirPlay installation is already running.':'Installing AirPlay…');watchAirPlayInstall()}else notify(button.dataset.action==='reboot'?'Restarting Pi…':'Request accepted.')}catch(error){button.disabled=false;if(button.dataset.action==='update')stopUpdateWatch();notify(error.message,true)}if(!['reboot','update','roon_install','airplay_install'].includes(button.dataset.action))setTimeout(()=>{button.disabled=false;loadSystem()},900)}));
