form.addEventListener('submit',async event=>{event.preventDefault();const sections=[...dirtySections];if(!sections.length||sections.some(section=>!validateSection(section)))return;const button=document.getElementById('save-settings');button.disabled=true;saveState.textContent='Saving…';try{for(const section of sections){const response=await fetch('/api/admin/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(sectionPayload(section))});const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not save')}if(sections.includes('bus')&&form.elements.lta_account_key.value){form.elements.lta_account_key.value='';document.getElementById('key-status').textContent='An AccountKey is configured.'}if(sections.includes('home')&&form.elements.home_assistant_token.value){form.elements.home_assistant_token.value='';document.getElementById('home-token-status').textContent='A Home Assistant token is configured.'}if(sections.includes('logging')&&form.elements.openobserve_password.value){form.elements.openobserve_password.value='';document.getElementById('openobserve-password-status').textContent='An OpenObserve password is configured.'}dirtySections.clear();dirtyFields.clear();notify('Settings saved.')}catch(error){notify(error.message,true)}finally{button.disabled=false;updateSaveBar()}});
const brightness=document.getElementById('display-brightness');brightness.addEventListener('input',()=>document.getElementById('brightness-value').textContent=`${brightness.value}%`);brightness.addEventListener('change',async()=>{try{const response=await fetch('/api/admin/brightness',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({brightness:Number(brightness.value)})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not set brightness');brightness.value=result.brightness;document.getElementById('brightness-value').textContent=`${result.brightness}%`;notify('Brightness saved.')}catch(error){notify(error.message,true)}});
