document.getElementById('save-auth').addEventListener('click',async()=>{const password=document.getElementById('admin-password').value,confirmation=document.getElementById('admin-password-confirm').value;if(password!==confirmation){notify('The new passwords do not match.',true);return}try{const response=await fetch('/api/admin/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:document.getElementById('admin-username').value,password,enabled:document.getElementById('auth-enabled').checked})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not save web access');location.href='/admin'}catch(error){notify(error.message,true)}});
document.getElementById('save-device-access').addEventListener('click',async()=>{const username=document.getElementById('device-username'),password=document.getElementById('device-password'),confirmation=document.getElementById('device-password-confirm');if(!username.checkValidity()||password.value.length<8||password.value.length>128){username.reportValidity();notify('Choose a device password of 8–128 characters.',true);return}if(password.value!==confirmation.value){notify('The device passwords do not match.',true);return}try{await action({action:'device_credentials',username:username.value,password:password.value,confirmation:confirmation.value});password.value='';confirmation.value='';notify('Device and SSH access updated. Web access will reload.');setTimeout(()=>location.href='/admin',900)}catch(error){notify(error.message,true)}});
document.getElementById('device-password').addEventListener('input',event=>{const value=event.target.value,simple=value.length>=8&&(value.length<12||/^[a-z]+$/i.test(value)||/^\d+$/.test(value));document.getElementById('device-password-help').textContent=simple?'This password is relatively easy to guess. RoonDeck will allow it if that is your choice.':'A longer, unique password is safer. A simple password is allowed if you choose it.'});

async function discoverBluOS(){const status=document.getElementById('bluos-status'),select=document.getElementById('bluos-discovered');status.textContent='Looking for BluOS players…';try{const response=await fetch('/roon/api/bluos/players',{cache:'no-store'}),data=await response.json();select.replaceChildren(new Option(data.players?.length?'Choose a player…':'No players found',''));for(const player of data.players||[])select.append(new Option(player.name,player.address));status.textContent=data.players?.length?'Select a player, then save changes.':'No player was found. Enter its address manually.'}catch(_){status.textContent='Discovery is unavailable. Enter the player address manually.'}}
document.getElementById('discover-bluos').addEventListener('click',discoverBluOS);document.getElementById('bluos-discovered').addEventListener('change',event=>{if(event.target.value){form.elements.bluos_player_address.value=event.target.value;markDirty()}});
function saveBluOSChoices(){const container=document.getElementById('bluos-inputs'),values=[...container.querySelectorAll('input[type="checkbox"]:checked')].map(item=>item.value),names=[...container.querySelectorAll('.input-choice')].map(row=>{const name=row.querySelector('input[type="text"]').value.trim();return name?`${row.dataset.id}=${name}`:''}).filter(Boolean);form.elements.bluos_visible_inputs.value=values.length?values.join(','):'__none__';form.elements.bluos_input_names.value=names.join(',');markDirty()}
async function loadBluOSInputs(){const container=document.getElementById('bluos-inputs'),selected=new Set(form.elements.bluos_visible_inputs.value.split(',').map(value=>value.trim()).filter(Boolean)),names=new Map(form.elements.bluos_input_names.value.split(',').map(value=>{const split=value.indexOf('=');return split<0?[value,'']:[value.slice(0,split),value.slice(split+1)]}));container.textContent='Loading inputs…';try{const response=await fetch('/roon/api/bluos/inputs',{cache:'no-store'}),data=await response.json();container.replaceChildren();if(!data.connected){container.textContent='Save the player address first, then load its inputs.';return}for(const input of data.inputs||[]){const row=document.createElement('div');row.className='input-choice';row.dataset.id=input.id;const label=document.createElement('label');label.className='check';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.value=input.id;checkbox.checked=!selected.size||selected.has(String(input.id));label.append(checkbox,document.createTextNode(` ${input.name}`));const alias=document.createElement('input');alias.type='text';alias.placeholder='Display name (optional)';alias.value=names.get(String(input.id))||'';checkbox.addEventListener('change',saveBluOSChoices);alias.addEventListener('input',saveBluOSChoices);row.append(label,alias);container.append(row)}}catch(_){container.textContent='Could not read inputs from the amplifier.'}}
document.getElementById('refresh-bluos-inputs').addEventListener('click',loadBluOSInputs);

