function updateNetworkRoute(){const node=document.getElementById('network-route'),transport=node.dataset.transport;node.textContent=!transport?'No active Ethernet or Wi-Fi connection':'This device → '+transport+(node.dataset.vpn==='Connected'?' → WireGuard VPN · '+node.dataset.mode:' → Network');}
function showNetworkTab(name){if(!['current','ethernet','wifi','vpn'].includes(name))name='current';activeNetworkTab=name;document.querySelectorAll('[data-network-panel]').forEach(panel=>panel.hidden=panel.dataset.networkPanel!==name);document.querySelectorAll('[data-network-tab]').forEach(button=>{const selected=button.dataset.networkTab===name;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1});recordAdminRoute()}
function showDisplayTab(name,record=true){activeDisplayTab=['appearance','touchscreen','hardware'].includes(name)?name:'appearance';document.querySelectorAll('[data-display-panel]').forEach(panel=>panel.hidden=panel.dataset.displayPanel!==activeDisplayTab);document.querySelectorAll('[data-display-tab]').forEach(button=>{const selected=button.dataset.displayTab===activeDisplayTab;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1});form.scrollTop=0;if(record)recordAdminRoute();}
document.querySelectorAll('[data-display-tab]').forEach(button=>{button.addEventListener('click',()=>showDisplayTab(button.dataset.displayTab));button.addEventListener('keydown',event=>{const tabs=[...document.querySelectorAll('[data-display-tab]')];let index=tabs.indexOf(button);if(event.key==='ArrowRight')index=(index+1)%tabs.length;else if(event.key==='ArrowLeft')index=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')index=0;else if(event.key==='End')index=tabs.length-1;else return;event.preventDefault();tabs[index].click();tabs[index].focus();});});
function showDiagnosticsView(name,record=true){activeDiagnosticTab=name==='performance'?'performance':'memory';document.querySelectorAll('[data-diagnostics-panel]').forEach(panel=>panel.hidden=panel.dataset.diagnosticsPanel!==activeDiagnosticTab);document.querySelectorAll('[data-diagnostics-tab]').forEach(button=>{const selected=button.dataset.diagnosticsTab===activeDiagnosticTab;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1});if(record)recordAdminRoute();window.dispatchEvent(new Event('admin-section-change'));}
document.querySelectorAll('[data-diagnostics-tab]').forEach(button=>{button.addEventListener('click',()=>showDiagnosticsView(button.dataset.diagnosticsTab));button.addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?'memory':event.key==='End'?'performance':activeDiagnosticTab==='memory'?'performance':'memory';const target=document.querySelector('[data-diagnostics-tab="'+next+'"]');target.click();target.focus();}})});
function restoreAdminRoute(){restoringRoute=true;let [tab,sub,view]=location.hash.slice(1).split('/').map(value=>{try{return decodeURIComponent(value)}catch(_){return''}});if(tab==='system'&&sub==='system-maintenance')tab='software';showTab(['overview','display','automation','services','system','controls','network','software','preview'].includes(tab)?tab:'overview');showService(document.querySelector('[data-service-tab="'+CSS.escape(sub||'bus')+'"]')?sub||'bus':'bus');openSystemSection(document.querySelector('[data-system-panel="'+CSS.escape(sub||'system-device')+'"]')?sub||'system-device':'system-device');showNetworkTab(sub||'current');showDisplayTab(tab==='display'?sub:'appearance',false);showDiagnosticsView(view||'memory',false);restoringRoute=false}
document.querySelectorAll('[data-tab]').forEach(button=>{button.tabIndex=button.getAttribute('aria-selected')==='true'?0:-1;button.addEventListener('keydown',event=>{const tabs=[...document.querySelectorAll('[data-tab]')];let index=tabs.indexOf(button);if(event.key==='ArrowDown')index=(index+1)%tabs.length;else if(event.key==='ArrowRight')index=(index+1)%tabs.length;else if(event.key==='ArrowLeft')index=(index+tabs.length-1)%tabs.length;else if(event.key==='ArrowUp')index=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')index=0;else if(event.key==='End')index=tabs.length-1;else return;event.preventDefault();tabs[index].click();tabs[index].focus()})});
