window.addEventListener('popstate',restoreAdminRoute);window.addEventListener('hashchange',restoreAdminRoute);setupHomeColours();restoreAdminRoute();syncNavigationName();loadDisplayMounting();loadInitialSettings();setTimeout(()=>resizeMultiline(form.elements.home_assistant_entities),500);

let findingZones=false;
async function findRoonZones(announce=false){if(findingZones)return;findingZones=true;const button=document.getElementById('scan-roon-zones'),status=document.getElementById('roon-zone-status'),select=form.elements.roon_zone_name;button.disabled=true;if(announce)status.textContent='Finding Roon zones…';try{const response=await fetch('/roon/api/state',{cache:'no-store',signal:AbortSignal.timeout(10000)});if(!response.ok)throw new Error('Could not reach the Roon controller.');const data=await response.json(),current=select.value,names=[...new Set((data.zones||[]).map(zone=>zone.name).filter(Boolean))].sort((a,b)=>a.localeCompare(b));select.replaceChildren(new Option('Follow the currently playing zone',''),...names.map(name=>new Option(name,name)));if(current&&!names.includes(current))select.add(new Option(current+' (not currently available)',current));select.value=current;status.textContent=names.length?`${names.length} zone${names.length===1?'':'s'} found. Choose one, then Save changes.`:data.connected?'No zones are available. Check Roon Settings → Audio.':'Connect and authorise RoonDeck in Roon Settings → Extensions. Over VPN, save the Roon Core address first.';if(announce)reportAdminActivity(names.length?`${names.length} Roon zones found.`:status.textContent,{source:'Roon'});}catch(error){status.textContent=error.message;if(announce)reportAdminActivity(error.message,{source:'Roon',error:true});}finally{findingZones=false;button.disabled=false;}}
document.getElementById('scan-roon-zones').addEventListener('click',()=>findRoonZones(true));
findRoonZones();
setInterval(()=>{if(!document.hidden&&activeTab==='services'&&activeService==='roon')findRoonZones();},10000);
